/** Encode a generated CSIL record to canonical CBOR bytes. */
fun <T> encode(value: T): ByteArray = CsilCbor.encode(csilToCborValue(value))

private fun csilToCborValue(value: Any?): CborValue = when (value) {
    null -> CborValue.CNull
    is CheckResult -> value.toCborValue()
    is HelloRequest -> value.toCborValue()
    is HelloResponse -> value.toCborValue()
    is GuestbookEntry -> value.toCborValue()
    is CreateGuestbookRequest -> value.toCborValue()
    is UpdateGuestbookRequest -> value.toCborValue()
    is DeleteGuestbookRequest -> value.toCborValue()
    is DeleteGuestbookResponse -> value.toCborValue()
    is GuestbookListRequest -> value.toCborValue()
    is GuestbookListResponse -> value.toCborValue()
    is EmptyRequest -> value.toCborValue()
    is DomainPublicKey -> value.toCborValue()
    is GetDomainKeysResponse -> value.toCborValue()
    is GetRevocationsRequest -> value.toCborValue()
    is GetRevocationsResponse -> value.toCborValue()
